operations.after:
// NOTE: N'...' prefix strings are still parsed as function-call-like
// forms (identifier + string_literal).

// Unicode-escape string U&'d\0061t' (scan.l xusstart), with the same
// continuation tail as string_literal.
unicode_string_literal: _ => token(/[uU]&'([^']|'')*'(([ \t\f\v]|--[^\n\r]*)*[\n\r]([ \t\n\r\f\v]+|--[^\n\r]*[\n\r])*'([^']|'')*')*/),

operations.before:
(void)payload;
if (!valid_symbols[DOLLAR_QUOTED_STRING]) return false;

skip_whitespace(lexer);

if (lexer->lookahead != '$') return false;

operations.after:
(void)payload;
if (!valid_symbols[DOLLAR_QUOTED_STRING] && !valid_symbols[COMMENT]) return false;

skip_whitespace(lexer);

/* Comments (scan.l comment / xc): -- to end of line, and block comments
 * that nest, so the first close of an inner comment does not end it. */
if (valid_symbols[COMMENT] && (lexer->lookahead == '-' || lexer->lookahead == '/')) {
  if (lexer->lookahead == '-') {
    lexer->advance(lexer, false);
    if (lexer->lookahead != '-') return false;
    while (lexer->lookahead != 0 && lexer->lookahead != '\n' && lexer->lookahead != '\r') {
      lexer->advance(lexer, false);
    }
    lexer->result_symbol = COMMENT;
    return true;
  }
  lexer->advance(lexer, false);
  if (lexer->lookahead != '*') return false;
  lexer->advance(lexer, false);
  unsigned depth = 1;
  while (lexer->lookahead != 0) {
    if (lexer->lookahead == '*') {
      lexer->advance(lexer, false);
      if (lexer->lookahead == '/') {
        lexer->advance(lexer, false);
        if (--depth == 0) {
          lexer->result_symbol = COMMENT;
          return true;
        }
      }
    } else if (lexer->lookahead == '/') {
      lexer->advance(lexer, false);
      if (lexer->lookahead == '*') {
        lexer->advance(lexer, false);
        depth++;
      }
    } else {
      lexer->advance(lexer, false);
    }
  }
  return false;
}

if (!valid_symbols[DOLLAR_QUOTED_STRING]) return false;
if (lexer->lookahead != '$') return false;
